#include <iostream>
#include <memory>
#include <vector>

struct TreeNode {
    int val;
    std::unique_ptr<TreeNode> left;
    std::unique_ptr<TreeNode> right;

    explicit TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}
};

void insert(std::unique_ptr<TreeNode>& root, int val) {
    if (!root) {
        root = std::make_unique<TreeNode>(val);
        return;
    }
    if (val < root->val) {
        insert(root->left, val);
    } else if (val > root->val) {
        insert(root->right, val);
    }
    // If val == root->val, duplicate is discarded
}

void inOrder(const TreeNode* node) {
    if (!node) return;
    inOrder(node->left.get());
    std::cout << node->val << " ";
    inOrder(node->right.get());
}

void preOrder(const TreeNode* node) {
    if (!node) return;
    std::cout << node->val << " ";
    preOrder(node->left.get());
    preOrder(node->right.get());
}

void postOrder(const TreeNode* node) {
    if (!node) return;
    postOrder(node->left.get());
    postOrder(node->right.get());
    std::cout << node->val << " ";
}

int main() {
    // Build the 15-node BST shown in Figure 12.22
    std::vector<int> values = {49, 28, 83, 18, 40, 71, 97, 11, 19, 32, 44, 69, 72, 92, 99};
    std::unique_ptr<TreeNode> root = nullptr;

    for (int v : values) {
        insert(root, v);
    }

    std::cout << "In-order: ";
    inOrder(root.get());
    std::cout << "\nPre-order: ";
    preOrder(root.get());
    std::cout << "\nPost-order: ";
    postOrder(root.get());
    std::cout << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <memory>

struct GradeNode {
    std::string lastName;
    double grade;
    std::unique_ptr<GradeNode> next;

    GradeNode(std::string name, double g)
        : lastName(std::move(name)), grade(g), next(nullptr) {}
};

void insertOrdered(std::unique_ptr<GradeNode>& head, const std::string& name, double grade) {
    auto newNode = std::make_unique<GradeNode>(name, grade);

    // Insertion at the head or in an empty list
    if (!head || name < head->lastName) {
        newNode->next = std::move(head);
        head = std::move(newNode);
        return;
    }

    GradeNode* current = head.get();
    while (current->next && current->next->lastName < name) {
        current = current->next.get();
    }

    newNode->next = std::move(current->next);
    current->next = std::move(newNode);
}

void printList(const GradeNode* current) {
    while (current != nullptr) {
        std::cout << current->lastName << ": " << current->grade << "\n";
        current = current->next.get();
    }
}

int main() {
    std::unique_ptr<GradeNode> startPtr = nullptr;

    // Initial nodes
    insertOrdered(startPtr, "Jones", 91.5);
    insertOrdered(startPtr, "Smith", 88.0);

    // Self-review exercise 12.4 items to insert in order
    insertOrdered(startPtr, "Adams", 85.0);
    insertOrdered(startPtr, "Thompson", 73.5);
    insertOrdered(startPtr, "Pritchard", 66.5);

    printList(startPtr.get());
    return 0;
}
